110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public String getHouseholdId() {
133	        return this.householdId;
134	    }
135	
136	    public void setHouseholdId(String householdId) {
137	        this.householdId = householdId;
138	    }
139	
140	    public Integer getNamesakeCount() {
141	        return this.namesakeCount;
142	    }
143	
144	    public void setNamesakeCount(Integer namesakeCount) {
145	        this.namesakeCount = namesakeCount;
146	    }
147	
148	    public String getMembershipNumber() {
149	        return this.membershipNumber;
150	    }
151	
152	    public void setMembershipNumber(String membershipNumber) {
153	        this.membershipNumber = membershipNumber;
154	    }
155	
156	    /**
157	     * Return this owner's name formatted as {@code LastName, FirstName}.
158	     */
159	    @Transient
160	    public String getDisplayName() {
161	        return this.getLastName() + ", " + this.getFirstName();
162	    }
163	
164	    /**
165	     * Return this owner's locality: the canonical region derived from the
166	     * {@link #getCity() city} via the fixed city-to-region table, or
167	     * {@code UNKNOWN} when the city is not in the table.
168	     */
169	    @Transient
170	    public String getLocality() {
171	        return CityRegions.regionOf(this.city);
172	    }
173	
174	    /**
175	     * Return this owner's membership level: starting at 1, plus 1 when the owner
176	     * has an email, plus 1 when the owner is uniquely named (a
177	     * {@link #getNamesakeCount() namesakeCount} of 0), capped at 3. Level 4 is
178	     * reserved for tenure.
179	     */
180	    @Transient
181	    public int getMembershipLevel() {
182	        int level = 1;
183	        boolean hasEmail = this.email != null && !this.email.isEmpty();
184	        if (hasEmail) {
185	            level++;
186	        }
187	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
188	        if (uniquelyNamed) {
189	            level++;
190	        }
191	        return Math.min(level, 3);
192	    }
193	
194	    protected Set<Pet> getPetsInternal() {
195	        if (this.pets == null) {
196	            this.pets = new HashSet<>();
197	        }
198	        return this.pets;
199	    }
200	
201	    protected void setPetsInternal(Set<Pet> pets) {
202	        this.pets = pets;
203	    }
204	
205	    public List<Pet> getPets() {
206	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
207	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
208	        return Collections.unmodifiableList(sortedPets);
209	    }
210	
211	    public void setPets(List<Pet> pets) {
212	        this.pets = new HashSet<>(pets);
213	    }
214	
215	    public void addPet(Pet pet) {
216	        getPetsInternal().add(pet);
217	        pet.setOwner(this);
218	    }
219	
220	    /**
221	     * Return the Pet with the given name, or null if none found for this Owner.
222	     *
223	     * @param name to test
224	     * @return true if pet name is already in use
225	     */
226	    public Pet getPet(String name) {
227	        return getPet(name, false);
228	    }
229	
230	    /**
231	     * Return the Pet with the given name, or null if none found for this Owner.
232	     *
233	     * @param name to test
234	     * @return true if pet name is already in use
235	     */
236	    public Pet getPet(String name, boolean ignoreNew) {
237	        name = name.toLowerCase();
238	        for (Pet pet : getPetsInternal()) {
239	            if (!ignoreNew || !pet.isNew()) {
240	                String compName = pet.getName();
241	                compName = compName.toLowerCase();
242	                if (compName.equals(name)) {
243	                    return pet;
244	                }
245	            }
246	        }
247	        return null;
248	    }
249	
250	    public Pet getPet(Integer petId) {
251	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
252	    }
253	
254	    @Override
255	    public String toString() {
256	        return new ToStringCreator(this)
257	
258	            .append("id", this.getId())
259	            .append("new", this.isNew())
260	            .append("lastName", this.getLastName())
261	            .append("firstName", this.getFirstName())
262	            .append("address", this.address)
263	            .append("city", this.city)
264	            .append("telephone", this.telephone)
265	            .append("email", this.email)
266	            .toString();
267	    }
268	}
